	assert(bool2, (("Bundle %* configKey must be nil or non-empty"):format(v1.id)))
	assert(var3.DevProducts[v1.productName], (("Unknown product %* for %*"):format(v1.productName, v1.id)))
	assert(not tbl3[v1.productName], (("Product %* is used by multiple bundles"):format(v1.productName)))
	assert(not tbl4[v1.productName], (("Product %* is used by an item"):format(v1.productName)))
	local var5 = v1.id
	assert(0 < (#v1.rewards), (("Bundle %* has no rewards"):format(var5)))
	if v1.comparePrice ~= nil then
		bool2 = false
		if type(v1.comparePrice) == "number" then
			bool2 = false
			if v1.comparePrice == math.floor(v1.comparePrice) then
				bool2 = 0 < v1.comparePrice
			end
		end

		var5 = v1.id
		assert(bool2, (("Bundle %* comparePrice must be a positive integer"):format(var5)))
	end

	if v1.totalStock ~= nil then
		bool2 = false
		if type(v1.totalStock) == "number" then
			bool2 = false
			if v1.totalStock == math.floor(v1.totalStock) then
				bool2 = 1 <= v1.totalStock
			end
		end

		var5 = v1.id
		assert(bool2, (("Bundle %* totalStock must be a positive integer"):format(var5)))
	end

	if v1.availableFrom ~= nil then
		var5 = v1.id
