		assert(not tbl3[v2.productName], (("Product %* is used by a bundle"):format(v2.productName)))
		assert(not tbl4[v2.productName], (("Product %* is used by multiple items"):format(v2.productName)))
		tbl4[v2.productName] = v2
	end

	tbl1[v1.id] = v1
